                .HasComputedColumnSql("(case when CONVERT([decimal](10,2),[SCORE])<=(0) then 'SIN SCORE' when CONVERT([decimal](10,2),[SCORE])>=(1) AND CONVERT([decimal](10,2),[SCORE])<(150) then 'MUY BAJO' when CONVERT([decimal](10,2),[SCORE])>=(150) AND CONVERT([decimal](10,2),[SCORE])<(250) then 'BAJO' when CONVERT([decimal](10,2),[SCORE])>=(250) AND CONVERT([decimal](10,2),[SCORE])<(350) then 'MEDIO BAJO' when CONVERT([decimal](10,2),[SCORE])>=(350) AND CONVERT([decimal](10,2),[SCORE])<(450) then 'MEDIO' when CONVERT([decimal](10,2),[SCORE])>=(450) AND CONVERT([decimal](10,2),[SCORE])<(550) then 'MEDIO ALTO' when CONVERT([decimal](10,2),[SCORE])>=(550) AND CONVERT([decimal](10,2),[SCORE])<(800) then 'ALTO' when CONVERT([decimal](10,2),[SCORE])>=(800) then 'MUY ALTO'  end)", false);
